import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { motion } from "framer-motion";

function About() {
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > window.innerHeight * 0.5);
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <div className="flex flex-col w-full min-h-screen">
      {/* Top Section (Full-screen Cover) */}
      <div className="relative w-full h-screen bg-red-600 flex flex-col items-center justify-center text-center p-10">
        <motion.img
          src="profile.avif"
          className="h-auto max-h-80 w-auto object-cover transition-all duration-300"
          alt="Profile"
          initial={{ opacity: 0, scale: 0.8 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ duration: 0.8, ease: "easeOut" }}
        />
        <motion.span
          className="font-extrabold text-white text-5xl lg:text-6xl mt-6"
          initial={{ opacity: 0, y: 30 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3, duration: 0.6, ease: "easeOut" }}
        >
          ABOUT ME
        </motion.span>
        <motion.p
          className="text-white text-lg max-w-3xl mt-4"
          initial={{ opacity: 0, y: 50 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.6, duration: 0.6, ease: "easeOut" }}
        >
          I'm a communication designer who thrives on creativity and
          connection. I see design as a way to tell stories and bring people
          together. When I'm not crafting visual magic, you'll find me
          experimenting with video games, making potions in my room, or
          planning my next travel adventure. I believe that great design
          starts with a spark of curiosity and a dash of fun, and I can't wait
          to share, explore, and learn more every day!
        </motion.p>

        {/* Scroll Indicator */}
        <motion.div
          className="absolute bottom-10 text-white text-lg"
          initial={{ opacity: 1 }}
          animate={{ opacity: scrolled ? 0 : 1 }}
          transition={{ duration: 0.5 }}
        >
          Scroll Down ↓
        </motion.div>
      </div>

      {/* Black Contact Section Appears on Scroll */}
      <motion.div
        className="bg-black flex flex-col items-center justify-center text-white w-full py-20 space-y-4"
        initial={{ opacity: 0, y: 100 }}
        animate={scrolled ? { opacity: 1, y: 0 } : {}}
        transition={{ duration: 0.8, ease: "easeOut" }}
      >
        {/* Contact and Navigation Lists Side by Side */}
        <div className="flex flex-wrap justify-between w-full max-w-4xl">
          {/* Personal Contact List */}
          <ul className="space-y-2">
            <li className="text-lg font-semibold">CONTACT</li>
            <li>
              <a
                href="mailto:sanskritichauhan1234@gmail.com"
                className="hover:underline"
              >
                sanskritichauhan1234@gmail.com
              </a>
            </li>
            <li>
              <a href="tel:+919867067656" className="hover:underline">
                +91 9867067656
              </a>
            </li>
          </ul>

          {/* Navigation Links */}
          <nav className="mt-2">
            <ul className="flex flex-col items-center space-y-2">
              <Link to="/" className="text-lg hover:underline">
                HOME
              </Link>
              <Link to="/about" className="text-lg hover:underline">
                ABOUT
              </Link>
              <Link to="/portfolio" className="text-lg hover:underline">
                PORTFOLIO
              </Link>
              <Link to="/photography" className="text-lg hover:underline">
                PHOTOGRAPHY
              </Link>
            </ul>
          </nav>
        </div>

        {/* Name Display */}
        <motion.div
          className="mt-16 text-center"
          initial={{ opacity: 0, scale: 0.8 }}
          animate={scrolled ? { opacity: 1, scale: 1 } : {}}
          transition={{ duration: 0.8, ease: "easeOut", delay: 0.3 }}
        >
          <span className="font-extrabold text-4xl lg:text-5xl whitespace-nowrap block">
            SANSKRITI CHAUHAN
          </span>
        </motion.div>
      </motion.div>
    </div>
  );
}

export default About;
